mapper.select:
SELECT id, user_id, song_id, parent_session_id, score_version, bpm, bpm_unit, idempotency_key, request_hash, start_note_idx, end_note_idx, recording_url, recording_bytes, recording_duration_ms, recording_sample_rate, recording_channels, status, fail_reason, analysis_attempt, analysis_started_at, started_at, ended_at, saved_at, memo, viewed_at, record_deleted_at, created_at
FROM practice_sessions
WHERE id = #{id}

SELECT id, user_id, song_id, parent_session_id, score_version, bpm, bpm_unit, idempotency_key, request_hash, start_note_idx, end_note_idx, recording_url, recording_bytes, recording_duration_ms, recording_sample_rate, recording_channels, status, fail_reason, analysis_attempt, analysis_started_at, started_at, ended_at, saved_at, memo, viewed_at, record_deleted_at, created_at
FROM practice_sessions
WHERE user_id = #{userId} AND idempotency_key = #{idempotencyKey}

mapper.insert:
INSERT INTO practice_sessions (user_id, song_id, parent_session_id, score_version, bpm, bpm_unit, idempotency_key, request_hash, start_note_idx, end_note_idx, status, started_at)
SELECT #{userId}, s.id, #{parentSessionId}, s.score_version,
       #{bpm}, #{bpmUnit}, #{idempotencyKey}, #{requestHash}, #{startNoteIdx}, #{endNoteIdx}, 'RECORDING', #{startedAt}
FROM songs s
WHERE s.id = #{songId} AND s.score_version = #{scoreVersion}
  AND s.status = 'PUBLISHED' AND s.is_scorable AND s.deleted_at IS NULL

mapper.update:
UPDATE practice_sessions
SET status = 'FAILED', fail_reason = #{failReason}
WHERE status = 'RECORDING' AND started_at < #{cutoff}

mapper.select:
SELECT id AS session_id, recording_url
FROM practice_sessions
WHERE saved_at IS NULL AND recording_url IS NOT NULL AND ended_at < #{cutoff} AND id > #{afterSessionId}
ORDER BY id
LIMIT #{limit}

mapper.update:
UPDATE practice_sessions
SET recording_url = NULL
WHERE id = #{sessionId} AND recording_url = #{recordingUrl} AND saved_at IS NULL AND ended_at < #{cutoff}

UPDATE practice_sessions
SET recording_url = #{recordingUrl}
WHERE id = #{sessionId} AND recording_url IS NULL AND record_deleted_at IS NULL

UPDATE practice_sessions
SET viewed_at = #{viewedAt}
WHERE id = #{sessionId} AND user_id = #{userId} AND saved_at IS NOT NULL AND record_deleted_at IS NULL AND viewed_at IS NULL

mapper.select:
SELECT status, fail_reason, started_at
FROM practice_sessions
WHERE id = #{sessionId} AND user_id = #{userId}
